function accessoryKey(catId, themeId) {
  return `${catId}_${themeId}`;
}
function accessorySrc(catId, themeId) {
  return IMG[accessoryKey(catId, themeId)];
}

const state = { color: 'cream', hat: null, bow: null, bag: null, shoes: null, dress_extra: [], blouse: [], skirt: [] };
const mannequinState = { hat: null, bow: null, bag: null, shoes: null, dress_extra: null, blouse: null, skirt: null };
const CLOTHING_IDS = ['dress_extra', 'blouse', 'skirt'];
const catClothingLayers = { dress_extra: [], blouse: [], skirt: [] };
let nextClothingLayerId = 1;
const CAT_LAYER_BEHIND = 5;
const CAT_LAYER_BASE = 10;
const CAT_LAYER_FRONT_MAX = 89;
let topCatLayerZ = 20;
const catLayerMode = {
  hat: 'front', bow: 'front', bag: 'front', shoes: 'front',
  dress_extra: 'front', blouse: 'front', skirt: 'front'
};

function setCatLayer(catId, mode, el = accEls[catId]) {
  if (!el) return;
  const nextMode = mode === 'behind' ? 'behind' : 'front';
  catLayerMode[catId] = nextMode;

  const isClothing = CLOTHING_IDS.includes(catId);
  if (nextMode === 'behind') {
    el.style.zIndex = String(CAT_LAYER_BEHIND);
  } else if (catId === 'hat' || catId === 'bow') {
    el.style.zIndex = '120';
  } else {
    topCatLayerZ = Math.min(Math.max(topCatLayerZ + 1, isClothing ? 20 : 40), CAT_LAYER_FRONT_MAX);
    el.style.zIndex = String(topCatLayerZ);
  }

  el.dataset.layer = nextMode;
  el.title = nextMode === 'behind'
    ? 'camada: atrás do gatinho — clique no chip para trazer para frente'
    : 'camada: frente do gatinho — clique no chip para enviar para trás';
}

function bringClothingToFront(el) {
  if (!el) return;
  const catId = Object.keys(accEls).find(id => accEls[id] === el);
  if (catId && catLayerMode[catId] === 'behind') return;
  if (catId) setCatLayer(catId, 'front', el);
}

function bringAccessoryToFront(catId) {
  const el = accEls[catId];
  if (!el) return;
  setCatLayer(catId, 'front', el);
}

function sendAccessoryBehind(catId) {
  const el = accEls[catId];
  if (!el) return;
  setCatLayer(catId, 'behind', el);
}

function toggleAccessoryLayer(catId) {
  const next = catLayerMode[catId] === 'behind' ? 'front' : 'behind';
  setCatLayer(catId, next);
  renderChips();
}

