function selectCatColor(id) {
  state.color = id;
  const color = CAT_COLORS[id];
  catBaseEl.src = IMG[color.key];
  if (catHeadOverlayEl) catHeadOverlayEl.src = IMG[color.key];
  refitAllCatSprites();
  catColorLabelEl.textContent = color.label;
  const visible = document.getElementById('cat-color-label-visible');
  if (visible) visible.textContent = color.label;
}

function moveCatColor(direction) {
  const currentIndex = catColorIds.indexOf(state.color);
  const nextIndex = (currentIndex + direction + catColorIds.length) % catColorIds.length;
  selectCatColor(catColorIds[nextIndex]);
}

document.getElementById('cat-color-prev').addEventListener('click', () => moveCatColor(-1));
document.getElementById('cat-color-next').addEventListener('click', () => moveCatColor(1));


