const TAB_GROUPS = [
  { id: 'dresses', label: 'vestidos', icon: 'assets/icon_tab_dress.png', cats: ['dress_extra'] },
  { id: 'blouses', label: 'blusas', icon: 'assets/icon_tab_blouse.png', cats: ['blouse'] },
  { id: 'skirts', label: 'saias', icon: 'assets/icon_tab_skirt.png', cats: ['skirt'] },
];

const categoryById = Object.fromEntries(ACCESSORY_CATEGORIES.map(c => [c.id, c]));

TAB_GROUPS.forEach((group, idx) => {
  const tab = document.createElement('button');
  tab.className = 'tab' + (idx === 1 ? ' active' : '');
  tab.dataset.group = group.id;
  tab.innerHTML = `<span class="tab-icon"><img src="${group.icon}" alt=""></span><span>${group.label}</span>`;
  tab.addEventListener('click', () => switchTab(group.id));
  tabsEl.appendChild(tab);

  const panel = document.createElement('div');
  panel.className = 'panel' + (idx === 1 ? ' active' : '');
  panel.id = `panel-${group.id}`;
  const grid = document.createElement('div');
  grid.className = 'grid';

  group.cats.forEach(catId => {
    const cat = categoryById[catId];
    cat.themes.forEach(themeId => {
      const card = document.createElement('div');
      card.className = 'item-card';
      card.draggable = true;
      card.dataset.cat = cat.id;
      card.dataset.color = themeId;
      card.innerHTML = `<span class="swatch"><img src="${accessorySrc(cat.id, themeId)}" alt="${THEME_LABEL[themeId]}"></span><span class="label">${THEME_LABEL[themeId]}</span>`;
      card.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', JSON.stringify({ source: 'wardrobe', cat: cat.id, color: themeId }));
        e.dataTransfer.effectAllowed = 'copy'; dragSource = 'wardrobe'; card.classList.add('dragging');
      });
      card.addEventListener('dragend', () => { card.classList.remove('dragging'); dragSource = null; });
      card.addEventListener('click', () => equipMannequin(cat.id, themeId));
      grid.appendChild(card);
    });
  });
  panel.appendChild(grid); panelsEl.appendChild(panel);
});

function switchTab(groupId) {
  document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.group === groupId));
  document.querySelectorAll('.panel').forEach(p => p.classList.toggle('active', p.id === `panel-${groupId}`));
}

