const MANNEQUIN_BODY_REF = SPRITE_CONTENT_BOX.mannequin;
const MANNEQUIN_CONTENT_FIT = {
  dress_extra: { x0: 0.08, x1: 0.92, y0: 0.13, y1: 0.52 },
  blouse: { x0: 0.06, x1: 0.94, y0: 0.125, y1: 0.42 },
  skirt: { x0: 0.06, x1: 0.94, y0: 0.335, y1: 0.52 },
};
const CONTENT_FIT_RELAX = 1.15;

function computeContentFitStyle(catId, themeId, opts = {}) {
  const canvas = opts.canvas || { w: 599, h: 755 };
  const body = opts.body || CAT_BODY_REF[opts.colorId || state.color] || CAT_BODY_REF.cream;
  const targets = opts.targets || CAT_CONTENT_FIT;
  const target = targets[catId];
  const item = SPRITE_CONTENT_BOX[accessoryKey(catId, themeId)];
  if (!target || !item) return null;

  const bodyW = (body.x1 - body.x0) * canvas.w;
  const bodyH = (body.y1 - body.y0) * canvas.h;
  const bodyX = body.x0 * canvas.w;
  const bodyY = body.y0 * canvas.h;


  const tw = (target.x1 - target.x0) * bodyW;
  const th = (target.y1 - target.y0) * bodyH;
  const cx = bodyX + (target.x0 + target.x1) / 2 * bodyW;
  const cy = bodyY + (target.y0 + target.y1) / 2 * bodyH;


  const iw = (item.x1 - item.x0) * item.w;
  const ih = (item.y1 - item.y0) * item.h;
  const sx = tw / iw;
  const sy = th / ih;
  const s = Math.min(sx, sy);

  const sxU = Math.min(sx, s * CONTENT_FIT_RELAX);
  const syU = Math.min(sy, s * CONTENT_FIT_RELAX);

  const fileW = item.w * sxU;
  const fileH = item.h * syU;
  const ccx = (item.x0 + item.x1) / 2;
  const ccy = (item.y0 + item.y1) / 2;
  const centerX = cx - (ccx - 0.5) * fileW;
  const centerY = cy - (ccy - 0.5) * fileH;

  return {
    width: `${fileW / canvas.w * 100}%`,
    height: `${fileH / canvas.h * 100}%`,
    left: `${centerX / canvas.w * 100}%`,
    top: `${centerY / canvas.h * 100}%`,
    transform: 'translate(-50%, -50%)',
  };
}

function applyContentFit(el, catId, themeId, opts = {}) {
  if (!el || !themeId) return;
  const style = computeContentFitStyle(catId, themeId, opts);
  if (!style) return;
  el.classList.remove('manual-position');
  el.style.width = style.width;
  el.style.height = style.height;
  el.style.objectFit = 'fill';
  el.style.left = style.left;
  el.style.top = style.top;
  el.style.transform = style.transform;
}

function fitCatSprite(el, catId, themeId) {
  applyContentFit(el, catId, themeId);
}

function fitMannequinSprite(el, catId, themeId) {
  applyContentFit(el, catId, themeId, {
    canvas: { w: SPRITE_CONTENT_BOX.mannequin.w, h: SPRITE_CONTENT_BOX.mannequin.h },
    body: MANNEQUIN_BODY_REF,
    targets: MANNEQUIN_CONTENT_FIT,
  });
}

function refitAllCatSprites() {
  ['hat', 'bow', 'bag', 'shoes'].forEach(catId => {
    const el = accEls[catId];
    if (!el || !state[catId] || el.classList.contains('manual-position')) return;
    fitCatSprite(el, catId, state[catId]);
  });
  CLOTHING_IDS.forEach(catId => {
    catClothingLayers[catId].forEach(layer => {
      if (layer.el && !layer.el.classList.contains('manual-position')) {
        fitCatSprite(layer.el, catId, layer.theme);
      }
    });
  });
}

function snapClothingLayerToCat(catId, layer) {
  if (!layer || !layer.el) return;
  fitCatSprite(layer.el, catId, layer.theme);
}

function snapBowToCat() {
  const el = accEls.bow;
  if (!el || !state.bow) return;
  fitCatSprite(el, 'bow', state.bow);
}

function snapAccessoryToCat(catId) {
  const el = accEls[catId];
  if (!el || !state[catId]) return;
  fitCatSprite(el, catId, state[catId]);
}

function clothingBaseEl(catId) {
  return accEls[catId];
}

function createClothingLayerEl(catId) {
  const base = clothingBaseEl(catId);
  const el = base.cloneNode(false);
  el.removeAttribute('id');
  el.classList.remove('hidden', 'pop', 'manual-position');
  base.parentNode.appendChild(el);
  return el;
}

function popLayerAnimation(el) {
  if (!el) return;
  el.classList.remove('pop');
  void el.offsetWidth;
  el.classList.add('pop');
}

function bindClothingLayerInteractions(catId, layer) {
  const el = layer.el;
  el.draggable = false;
  el.classList.add('positionable');

  el.addEventListener('dblclick', e => {
    e.preventDefault();
    layer.mode = layer.mode === 'behind' ? 'front' : 'behind';
    setCatLayer(catId, layer.mode, el);
    renderChips();
  });

  installFreeDrag(
    el,
    () => catClothingLayers[catId].includes(layer) ? { cat: catId, color: layer.theme } : null,
    'cat',
    equipMannequinAtDropPoint,
    catId
  );
}

function addClothingLayer(catId, themeId) {
  const layers = catClothingLayers[catId];
  const el = layers.length === 0 ? clothingBaseEl(catId) : createClothingLayerEl(catId);
  if (!el) return null;

  el.src = accessorySrc(catId, themeId);
  el.classList.remove('hidden');

  const uid = nextClothingLayerId++;
  const layer = { uid, theme: themeId, el, mode: 'front' };
  layers.push(layer);
  state[catId].push({ uid, theme: themeId });

  setCatLayer(catId, 'front', el);
  bindClothingLayerInteractions(catId, layer);
  snapClothingLayerToCat(catId, layer);
  popLayerAnimation(el);

  return layer;
}

function removeClothingLayer(catId, uid) {
  const layers = catClothingLayers[catId];
  const idx = layers.findIndex(l => l.uid === uid);
  if (idx === -1) return;
  const [layer] = layers.splice(idx, 1);
  state[catId] = state[catId].filter(l => l.uid !== uid);

  if (layer.el === clothingBaseEl(catId)) {
    clearLayer(layer.el);
  } else {
    layer.el.remove();
  }
}

function clearClothingCategory(catId) {
  [...catClothingLayers[catId]].forEach(layer => removeClothingLayer(catId, layer.uid));
}

function renderCatClothingLayers() {
  CLOTHING_IDS.forEach(catId => {
    catClothingLayers[catId].forEach(layer => {
      if (layer.el !== clothingBaseEl(catId)) layer.el.remove();
    });
    catClothingLayers[catId] = [];
    clearLayer(clothingBaseEl(catId));

    const wanted = state[catId];
    state[catId] = [];
    wanted.forEach(({ theme }) => addClothingLayer(catId, theme));
  });
}

dropzone.addEventListener('dragover', e => {
  e.preventDefault();
  if (dragSource !== 'mannequin' && dragSource !== 'wardrobe') {
    e.dataTransfer.dropEffect = 'none';
    dropzone.classList.remove('drop-hover');
    return;
  }
  e.dataTransfer.dropEffect = 'copy';
  dropzone.classList.add('drop-hover');
});
dropzone.addEventListener('dragleave', () => dropzone.classList.remove('drop-hover'));
dropzone.addEventListener('drop', e => {
  e.preventDefault();
  dropzone.classList.remove('drop-hover');
  const data = safeParse(e.dataTransfer.getData('text/plain'));
  if (!data || !data.cat || !data.color) return;
  if (data.source === 'wardrobe') {
    equipMannequin(data.cat, data.color);
  } else if (data.source !== 'mannequin') {
    return;
  }
  equipAtDropPoint(data.cat, data.color, e.clientX, e.clientY);
});

function equipAtDropPoint(catId, themeId, clientX, clientY) {
  equip(catId, themeId);
  if (CLOTHING_IDS.includes(catId) || categoryById[catId]) return;

  const stage = document.querySelector('.cat-stage');
  const bounds = stage.getBoundingClientRect();
  const el = accEls[catId];
  if (!el || !bounds.width || !bounds.height) return;

  el.classList.add('positionable', 'manual-position');
  el.style.left = `${(clientX - bounds.left) / bounds.width * 100}%`;
  el.style.top = `${(clientY - bounds.top) / bounds.height * 100}%`;
}

function equipMannequinAtDropPoint(catId, themeId, clientX, clientY) {
  if (!CLOTHING_IDS.includes(catId)) return;
  equipMannequin(catId, themeId);

  const stage = document.querySelector('.mannequin-doll-stage');
  const bounds = stage.getBoundingClientRect();
  const el = mannequinEls[catId];
  if (!el || !bounds.width || !bounds.height) return;

  el.style.left = `${(clientX - bounds.left) / bounds.width * 100}%`;
  el.style.top = `${(clientY - bounds.top) / bounds.height * 100}%`;
  el.style.transform = 'translate(-50%, -50%)';
}


trash.addEventListener('drop', e => {
  e.preventDefault();
  trash.classList.remove('drop-hover');
  const data = safeParse(e.dataTransfer.getData('text/plain'));
  if (!data) return;
  if (data.source === 'chip') {
    unequip(data.cat);
  } else if (data.source === 'chip-layer') {
    removeClothingLayer(data.cat, data.uid);
    refreshCards(data.cat);
    renderChips();
    updateCaption();
  } else if (data.source === 'mannequin') {
    unequipMannequin(data.cat);
  }
});


trash.addEventListener('click', () => clearMannequin());

function safeParse(str) { try { return JSON.parse(str); } catch { return null; } }


function clearLayer(el, resetPosition = true) {
  if (!el) return;
  el.classList.add('hidden');
  el.classList.remove('pop');
  el.classList.remove('positionable', 'manual-position');
  el.removeAttribute('src');
  el.draggable = false;
  if (resetPosition) {
    el.style.removeProperty('left');
    el.style.removeProperty('top');
  }
}

function renderClothes(targetState, targetEls) {
  CLOTHING_IDS.forEach(id => clearLayer(targetEls[id], !targetState[id]));
  CLOTHING_IDS.forEach(id => {
    if (!targetState[id]) return;
    const el = targetEls[id];
    if (!el) return;
    el.src = accessorySrc(id, targetState[id]);
    el.classList.remove('hidden');
    el.draggable = false;
  });
}

function selectClothing(targetState, targetEls, catId, themeId) {
  targetState[catId] = themeId;
  renderClothes(targetState, targetEls);
}

function equip(catId, themeId) {
  if (CLOTHING_IDS.includes(catId)) {
    addClothingLayer(catId, themeId);
  } else {
    state[catId] = themeId;
    const el = accEls[catId];
    el.src = accessorySrc(catId, themeId);
    el.classList.remove('hidden');
    el.classList.add('positionable');
    setCatLayer(catId, 'front', el);
    if (catId === 'bow') snapBowToCat();
    else snapAccessoryToCat(catId);
    popAnimation(catId);
  }

  ACCESSORY_CATEGORIES.forEach(cat => refreshCards(cat.id));
  renderChips();
  updateCaption();
}

function unequip(catId) {
  if (CLOTHING_IDS.includes(catId)) {
    clearClothingCategory(catId);
  } else {
    state[catId] = null;
    clearLayer(accEls[catId]);
  }
  refreshCards(catId);
  renderChips();
  updateCaption();
}

function popAnimation(catId) {
  popLayerAnimation(accEls[catId]);
}

function refreshCards(catId) {
  const isClothing = CLOTHING_IDS.includes(catId);
  document.querySelectorAll(`.item-card[data-cat="${catId}"]`).forEach(card => {
    const active = isClothing
      ? state[catId].some(layer => layer.theme === card.dataset.color)
      : state[catId] === card.dataset.color;
    card.classList.toggle('selected', active);
  });
}

function updateBadge(catId) { }

function renderChips() {
  wornChipsEl.innerHTML = '';
  ACCESSORY_CATEGORIES.forEach(cat => {
    if (CLOTHING_IDS.includes(cat.id)) {
      catClothingLayers[cat.id].forEach(layer => addClothingChip(cat.id, layer));
    } else if (state[cat.id]) {
      addChip(cat.id);
    }
  });
}

function addChip(catId) {
  const cat = ACCESSORY_CATEGORIES.find(c => c.id === catId);
  const themeId = state[catId];
  const src = accessorySrc(catId, themeId);

  const chip = document.createElement('div');
  chip.className = 'chip';
  chip.draggable = true;
  chip.innerHTML = `<img src="${src}" alt=""><span>${cat.label} — ${THEME_LABEL[themeId]}</span>`;

  const layerBtn = document.createElement('button');
  layerBtn.textContent = '↕';
  layerBtn.title = catLayerMode[catId] === 'behind'
    ? 'Trazer para frente'
    : 'Enviar para trás do gatinho';
  layerBtn.setAttribute('aria-label', layerBtn.title);
  layerBtn.addEventListener('click', e => {
    e.preventDefault();
    e.stopPropagation();
    toggleAccessoryLayer(catId);
  });
  chip.appendChild(layerBtn);

  const removeBtn = document.createElement('button');
  removeBtn.textContent = '✕';
  removeBtn.title = 'Remover';
  removeBtn.addEventListener('click', e => {
    e.preventDefault();
    e.stopPropagation();
    unequip(catId);
  });
  chip.appendChild(removeBtn);

  chip.addEventListener('dragstart', e => {
    const payload = { source: 'chip', cat: catId };
    e.dataTransfer.setData('text/plain', JSON.stringify(payload));
    e.dataTransfer.effectAllowed = 'move';
    chip.classList.add('dragging');
  });
  chip.addEventListener('dragend', () => chip.classList.remove('dragging'));

  wornChipsEl.appendChild(chip);
}

function addClothingChip(catId, layer) {
  const cat = ACCESSORY_CATEGORIES.find(c => c.id === catId);
  const src = accessorySrc(catId, layer.theme);

  const chip = document.createElement('div');
  chip.className = 'chip';
  chip.draggable = true;
  chip.innerHTML = `<img src="${src}" alt=""><span>${cat.label} — ${THEME_LABEL[layer.theme]}</span>`;

  const layerBtn = document.createElement('button');
  layerBtn.textContent = '↕';
  layerBtn.title = layer.mode === 'behind'
    ? 'Trazer para frente'
    : 'Enviar para trás do gatinho';
  layerBtn.setAttribute('aria-label', layerBtn.title);
  layerBtn.addEventListener('click', e => {
    e.preventDefault();
    e.stopPropagation();
    layer.mode = layer.mode === 'behind' ? 'front' : 'behind';
    setCatLayer(catId, layer.mode, layer.el);
    renderChips();
  });
  chip.appendChild(layerBtn);

  const removeBtn = document.createElement('button');
  removeBtn.textContent = '✕';
  removeBtn.title = 'Remover';
  removeBtn.addEventListener('click', e => {
    e.preventDefault();
    e.stopPropagation();
    removeClothingLayer(catId, layer.uid);
    refreshCards(catId);
    renderChips();
    updateCaption();
  });
  chip.appendChild(removeBtn);

  chip.addEventListener('dragstart', e => {
    const payload = { source: 'chip-layer', cat: catId, uid: layer.uid };
    e.dataTransfer.setData('text/plain', JSON.stringify(payload));
    e.dataTransfer.effectAllowed = 'move';
    chip.classList.add('dragging');
  });
  chip.addEventListener('dragend', () => chip.classList.remove('dragging'));

  wornChipsEl.appendChild(chip);
}

function updateCaption() {
  const parts = ACCESSORY_CATEGORIES
    .filter(c => CLOTHING_IDS.includes(c.id) ? state[c.id].length > 0 : state[c.id])
    .map(c => CATEGORY_NAME[c.id]);
  captionEl.textContent = parts.length
    ? `look atual: ${parts.join(' + ')} ♡`
    : 'o que devo vestir hoje? ♡';
}

function resetCatAccessoryPositions() {
  ['hat', 'bow', 'bag', 'shoes'].forEach(catId => {
    const el = accEls[catId];
    if (!el || !state[catId]) return;
    fitCatSprite(el, catId, state[catId]);
    setCatLayer(catId, 'front', el);
  });
  CLOTHING_IDS.forEach(catId => {
    catClothingLayers[catId].forEach(layer => {
      layer.mode = 'front';
      snapClothingLayerToCat(catId, layer);
      setCatLayer(catId, 'front', layer.el);
    });
  });
}


document.getElementById('btn-clear').addEventListener('click', () => {
  ACCESSORY_CATEGORIES.forEach(cat => unequip(cat.id));
});

document.getElementById('btn-random').addEventListener('click', () => {
  const colorIds = Object.keys(CAT_COLORS);
  selectCatColor(colorIds[Math.floor(Math.random() * colorIds.length)]);

  const randomOf = list => list[Math.floor(Math.random() * list.length)];

  ACCESSORY_CATEGORIES.forEach(cat => unequip(cat.id));

  const dressThemes = categoryById.dress_extra.themes;
  const blouseThemes = categoryById.blouse.themes;
  const skirtThemes = categoryById.skirt.themes;

  if (Math.random() < 0.7 && dressThemes.length) {
    equip('dress_extra', randomOf(dressThemes));
  }
  if (Math.random() < 0.7 && blouseThemes.length) {
    equip('blouse', randomOf(blouseThemes));
  }
  if (Math.random() < 0.7 && skirtThemes.length) {
    equip('skirt', randomOf(skirtThemes));
  }

  ACCESSORY_CATEGORIES
    .filter(cat => !CLOTHING_IDS.includes(cat.id))
    .forEach(cat => {
      if (Math.random() < 0.85 && cat.themes.length) {
        equip(cat.id, randomOf(cat.themes));
      }
    });

  resetCatAccessoryPositions();
  renderChips();
  updateCaption();
});

function equipMannequin(catId, themeId) {
  if (!CLOTHING_IDS.includes(catId)) return;
  if (CLOTHING_IDS.includes(catId)) {
    selectClothing(mannequinState, mannequinEls, catId, themeId);
    fitMannequinSprite(mannequinEls[catId], catId, themeId);
    bringClothingToFront(mannequinEls[catId]);
  } else {
    const previous = mannequinState[catId];
    if (previous && previous !== themeId && mannequinColorHistory[catId]) {
      mannequinColorHistory[catId].push(previous);
    }
    mannequinState[catId] = themeId;
    guideSelection[catId] = themeId;
    const el = mannequinEls[catId];
    el.src = accessorySrc(catId, themeId);
    el.classList.remove('hidden');
    el.draggable = true;
    updateGuideSlot(catId);
  }
  popMannequinAnimation(catId);
  updateMannequinCaption();
}

function unequipMannequin(catId) {
  mannequinState[catId] = null;
  if (CLOTHING_IDS.includes(catId)) renderClothes(mannequinState, mannequinEls);
  else clearLayer(mannequinEls[catId]);
  updateMannequinCaption();
}

function clearMannequin() {
  Object.keys(mannequinState).forEach(catId => {
    mannequinState[catId] = null;
    clearLayer(mannequinEls[catId]);
  });
  updateMannequinCaption();
}

function popMannequinAnimation(catId) {
  const el = mannequinEls[catId];
  el.classList.remove('pop');
  void el.offsetWidth;
  el.classList.add('pop');
}

function updateMannequinCaption() {
  const dressed = ACCESSORY_CATEGORIES.some(c => mannequinState[c.id]);
  mannequinCaption.textContent = dressed
    ? 'arraste a peça até o ponto desejado no gatinho 🐾'
    : 'vista o manequim primeiro. . .';
}

Object.entries(mannequinEls).forEach(([catId, el]) => {
  try {
    el.draggable = false;
    el.addEventListener('dragstart', e => {
      if (!mannequinState[catId]) { e.preventDefault(); return; }
      e.dataTransfer.setData('text/plain', JSON.stringify({
        source: 'mannequin', cat: catId, color: mannequinState[catId]
      }));
      e.dataTransfer.effectAllowed = 'copy';
      dragSource = 'mannequin';
      el.classList.add('dragging');
    });
    el.addEventListener('dragend', () => {
      el.classList.remove('dragging');
      dragSource = null;
    });
  } catch (err) {
    console.error(`[dress-up] falha ao configurar arraste (manequim) de "${catId}":`, err);
  }
});

function installFreeDrag(el, getState, source, onDropInsideOther, catId) {
  if (!el) return;

  el.draggable = false;

  el.addEventListener('pointerdown', e => {
    if (el.classList.contains('hidden') || e.button !== 0) return;

    if (CLOTHING_IDS.includes(catId)) {
      if (el.dataset.layer !== 'behind') setCatLayer(catId, 'front', el);
    }

    const originalStyle = {
      left: el.style.left,
      top: el.style.top,
      transform: el.style.transform,
      zIndex: el.style.zIndex,
      manualPosition: el.classList.contains('manual-position')
    };

    e.preventDefault();
    const stage = el.parentElement;
    const bounds = stage.getBoundingClientRect();
    const rect = el.getBoundingClientRect();
    const offsetX = e.clientX - (rect.left + rect.width / 2);
    const offsetY = e.clientY - (rect.top + rect.height / 2);
    let moved = false;
    const target = source === 'mannequin' ? dropzone : mannequinDropzone;
    const hoverEl = target;

    el.dataset.pointerDragged = 'false';
    el.setPointerCapture(e.pointerId);
    el.classList.add('dragging');

    const restoreSourcePosition = () => {
      el.style.left = originalStyle.left;
      el.style.top = originalStyle.top;
      el.style.transform = originalStyle.transform;
      el.style.zIndex = originalStyle.zIndex;
      el.classList.toggle('manual-position', originalStyle.manualPosition);
    };

    const isOverTarget = (clientX, clientY) => {
      if (!target) return false;
      const targetBounds = target.getBoundingClientRect();
      return clientX >= targetBounds.left &&
        clientX <= targetBounds.right &&
        clientY >= targetBounds.top &&
        clientY <= targetBounds.bottom;
    };

    const move = moveEvent => {
      moved = true;
      el.dataset.pointerDragged = 'true';

      const x = moveEvent.clientX - bounds.left - offsetX;
      const y = moveEvent.clientY - bounds.top - offsetY;
      el.style.left = `${x / bounds.width * 100}%`;
      el.style.top = `${y / bounds.height * 100}%`;
      el.style.transform = 'translate(-50%, -50%)';

      hoverEl?.classList.toggle('drop-hover', isOverTarget(moveEvent.clientX, moveEvent.clientY));
    };

    const end = endEvent => {
      el.classList.remove('dragging');
      el.releasePointerCapture?.(e.pointerId);
      el.removeEventListener('pointermove', move);
      el.removeEventListener('pointerup', end);
      el.removeEventListener('pointercancel', end);
      hoverEl?.classList.remove('drop-hover');

      if (!moved) return;

      const current = getState();
      if (!current?.color || !current?.cat) {
        restoreSourcePosition();
        return;
      }

      if (!target) {
        restoreSourcePosition();
        return;
      }

      const insideTarget = isOverTarget(endEvent.clientX, endEvent.clientY);

      if (insideTarget) {
        onDropInsideOther(current.cat, current.color, endEvent.clientX, endEvent.clientY);
        restoreSourcePosition();
      } else {
        el.classList.add('manual-position');
      }
    };

    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
  });
}

