Object.entries(accEls).forEach(([catId, el]) => {
  if (CLOTHING_IDS.includes(catId)) return;
  try {
    el.addEventListener('dblclick', e => {
      e.preventDefault();
      toggleAccessoryLayer(catId);
    });

    el.draggable = false;
    el.addEventListener('dragstart', e => {
      if (!state[catId]) { e.preventDefault(); return; }
      e.dataTransfer.setData('text/plain', JSON.stringify({
        source: 'cat', cat: catId, color: state[catId]
      }));
      e.dataTransfer.effectAllowed = 'copy';
      dragSource = 'cat';
      el.classList.add('dragging');
    });

    el.addEventListener('dragend', () => {
      el.classList.remove('dragging');
      dragSource = null;
    });

    installFreeDrag(
      el,
      () => state[catId] ? { cat: catId, color: state[catId] } : null,
      'cat',
      equipMannequinAtDropPoint,
      catId
    );
  } catch (err) {
    console.error(`[dress-up] falha ao configurar arraste livre (gatinho) de "${catId}":`, err);
  }
});

mannequinDropzone.addEventListener('dragover', e => {
  e.preventDefault();
  if (dragSource === 'cat') {
    e.dataTransfer.dropEffect = 'copy';
    mannequinDropzone.classList.add('drop-hover');
  } else if (dragSource === 'wardrobe') {
    e.dataTransfer.dropEffect = 'copy';
    mannequinDropzone.classList.add('drop-hover');
  } else {
    e.dataTransfer.dropEffect = 'none';
  }
});

mannequinDropzone.addEventListener('dragleave', () => mannequinDropzone.classList.remove('drop-hover'));
mannequinDropzone.addEventListener('drop', e => {
  e.preventDefault();
  mannequinDropzone.classList.remove('drop-hover');
  const data = safeParse(e.dataTransfer.getData('text/plain'));
  if (!data || !data.cat || !data.color) return;

  if (data.source === 'cat') {
    equipMannequinAtDropPoint(data.cat, data.color, e.clientX, e.clientY);
  } else if (data.source === 'wardrobe') {
    equipMannequin(data.cat, data.color);
  }
});

