const GUIDE_ACCESSORIES = ['hat', 'bow', 'bag', 'shoes'];

function getGuideSlot(catId) {
  return document.querySelector(`.guide-slot[data-guide-cat="${catId}"]`);
}

function getGuideThemeIndex(catId, themeId) {
  const cat = categoryById[catId];
  return cat ? Math.max(0, cat.themes.indexOf(themeId)) : 0;
}

function updateGuideSlot(catId) {
  const slot = getGuideSlot(catId);
  if (!slot) return;
  const item = slot.querySelector('.guide-item');
  const count = slot.querySelector('.guide-count');
  const cat = categoryById[catId];
  const selected = guideSelection[catId] || cat.themes[0];
  guideSelection[catId] = selected;
  item.src = accessorySrc(catId, selected);
  item.dataset.guideColor = selected;
  item.alt = `${cat.label} — ${THEME_LABEL[selected]}`;
  count.textContent = `${getGuideThemeIndex(catId, selected) + 1}/${cat.themes.length}`;
}

function cycleMannequinAccessory(catId, direction) {
  const cat = categoryById[catId];
  if (!cat || !cat.themes.length) return;

  const current = guideSelection[catId] || cat.themes[0];
  const idx = cat.themes.indexOf(current);
  const next = cat.themes[(idx + direction + cat.themes.length) % cat.themes.length];

  guideSelection[catId] = next;
  updateGuideSlot(catId);
}

function moveGuideMouse(item, clientX, clientY) {
  const stage = item.closest('.guide-stage');
  if (!stage) return;
  let hint = stage.querySelector('.guide-mouse-hint');
  if (!hint) {
    hint = document.createElement('img');
    hint.className = 'guide-mouse-hint';
    hint.src = 'assets/pixel-hand.png';
    hint.alt = '';
    stage.appendChild(hint);
  }
  const sr = stage.getBoundingClientRect();
  const r = item.getBoundingClientRect();
  const x = clientX != null ? clientX - sr.left + 8 : r.right - sr.left - 2;
  const y = clientY != null ? clientY - sr.top + 4 : r.bottom - sr.top - 2;
  hint.style.left = `${Math.max(0, x)}px`;
  hint.style.top = `${Math.max(0, y)}px`;
  hint.classList.add('show');
}

function hideGuideMouse(stage) {
  const hint = stage?.querySelector('.guide-mouse-hint');
  if (hint) hint.classList.remove('show');
}

function initGuideAccessories() {
  GUIDE_ACCESSORIES.forEach(catId => {
    try {
      const slot = getGuideSlot(catId);
      if (!slot) return;
      const item = slot.querySelector('.guide-item');
      const prev = slot.querySelector('.guide-prev');
      const next = slot.querySelector('.guide-next');
      if (!item || !prev || !next) return;

      updateGuideSlot(catId);

      item.addEventListener('click', () => {
        const selectedColor = guideSelection[catId];
        equip(catId, selectedColor);
        updateGuideSlot(catId);
      });

      item.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', JSON.stringify({
          source: 'wardrobe', cat: catId, color: guideSelection[catId]
        }));
        e.dataTransfer.effectAllowed = 'copy';
        dragSource = 'wardrobe';
        item.classList.add('dragging');
      });
      item.addEventListener('dragend', () => {
        item.classList.remove('dragging');
        dragSource = null;
      });

      item.addEventListener('pointerenter', e => moveGuideMouse(item, e.clientX, e.clientY));
      item.addEventListener('pointermove', e => moveGuideMouse(item, e.clientX, e.clientY));
      item.addEventListener('pointerleave', () => hideGuideMouse(slot.closest('.guide-stage')));

      prev.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        cycleMannequinAccessory(catId, -1);
      });
      next.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        cycleMannequinAccessory(catId, 1);
      });
    } catch (err) {
      console.error(`[dress-up] falha ao configurar o acessório "${catId}":`, err);
    }
  });
}


